&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1589&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Carduri AS\n(\n    SELECT\n        Id AS CardId,\n        CAST(N&#39;BCR&#39; AS NVARCHAR(10)) AS Banca,\n        CodSucursala,\n        Marca,\n        Nume,\n        CONVERT(NVARCHAR(50), CNP) AS CNP,\n        ContIBAN,\n        CAST(ISNULL(Valid, 0) AS BIT) AS Valid\n    FROM app.CardBCR\n\n    UNION ALL\n\n    SELECT Id, N&#39;BRD&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardBRD\n\n    UNION ALL\n\n    SELECT Id, N&#39;BT&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardBT\n\n    UNION ALL\n\n    SELECT Id, N&#39;CEC&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardCEC\n\n    UNION ALL\n\n    SELECT Id, N&#39;ING&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardING\n\n    UNION ALL\n\n    SELECT Id, N&#39;EXM&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardEXM\n\n    UNION ALL\n\n    SELECT Id, N&#39;RZB&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardRZB\n\n    UNION ALL\n\n    SELECT Id, N&#39;UNI&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardUNI\n\n    UNION ALL\n\n    SELECT Id, N&#39;ALTE&#39;, CodSucursala, Marca, Nume,\n           CONVERT(NVARCHAR(50), CNP), ContIBAN,\n           CAST(ISNULL(Valid, 0) AS BIT)\n    FROM app.CardALTE\n)\n\nSELECT\n    Banca + N&#39;-&#39; + CONVERT(NVARCHAR(20), CardId) AS RowId,\n    CardId,\n    Banca,\n    CodSucursala,\n    Marca,\n    Nume,\n    CNP,\n    ContIBAN,\n    Valid,\n    CASE\n        WHEN Valid = 1 THEN N&#39;Activ&#39;\n        ELSE N&#39;Inactiv&#39;\n    END AS StatusCard\nFROM Carduri\nWHERE CodSucursala = @CodSucursala\nORDER BY\n    CASE WHEN Valid = 1 THEN 0 ELSE 1 END,\n    Nume,\n    Marca,\n    Banca;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;}],&quot;IdColumn&quot;:&quot;RowId&quot;,&quot;SqlQueryColumns&quot;:&quot;RowId\nCardId\nBanca\nCodSucursala\nMarca\nNume\nCNP\nContIBAN\nValid\nStatusCard&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:null,&quot;Name&quot;:&quot;RowId&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CardId&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Banca&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Marca&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Nume&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;CNP&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;ContIBAN&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;Valid&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:null,&quot;Name&quot;:&quot;StatusCard&quot;,&quot;TypeStr&quot;:&quot;System.Void, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:false,&quot;DefaultValue&quot;:null}]}&lt;/DataSource&gt;
